//! Golden cross-language test: the desktop must decrypt exactly what the Go server
//! writes. The fixture under `fixtures/depot` is generated by `genfixture` from the
//! Go `internal/depot` package; this test reads it back and reassembles the files.
//!
//! Regenerate with:
//!   cd backend && go run ./cmd/genfixture <srcdir> ../desktop/src-tauri/fixtures/depot
//! where <srcdir> contains a.txt="hello world" and sub/b.txt="second file content".

use app_lib::depot::crypto;
use app_lib::depot::FileDepot;

fn fixture_root() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("fixtures")
        .join("depot")
}

fn expected_digest() -> String {
    let p = fixture_root().join("DIGEST");
    std::fs::read_to_string(&p)
        .unwrap_or_else(|e| panic!("read {}: {e}", p.display()))
        .trim()
        .to_string()
}

#[test]
fn go_release_assembles_and_verifies_in_rust() {
    let root = fixture_root();
    let digest = expected_digest();
    let depot = FileDepot::open(&root, &digest).expect("open release");

    assert_eq!(depot.manifest.format, "gamedepot-release");
    assert_eq!(depot.manifest.version, 1);
    assert_eq!(depot.manifest.chunk_size, 4 * 1024 * 1024);

    let read = |sha: &str| depot.read_object(sha);
    let mut results = std::collections::HashMap::new();
    for file in &depot.manifest.files {
        let bytes = crypto::assemble_file(&depot.manifest, file, |sha| read(sha))
            .unwrap_or_else(|e| panic!("assemble {}: {e}", file.path));
        results.insert(file.path.clone(), bytes);
    }

    assert_eq!(results.len(), 2);
    assert_eq!(results["a.txt"], b"hello world");
    assert_eq!(results["sub/b.txt"], b"second file content");
}

#[test]
fn tampered_object_is_rejected() {
    let root = fixture_root();
    let digest = expected_digest();
    let depot = FileDepot::open(&root, &digest).expect("open release");

    // Flip a byte of the first file's single chunk and confirm verification fails.
    let file = depot.manifest.files.iter().find(|f| f.path == "a.txt").unwrap();
    let sha = &file.chunks[0].sha256;
    let mut ct = depot.read_object(sha).unwrap();
    let last = ct.len() - 1;
    ct[last] ^= 0xFF;

    let key = crypto::key_bytes(&depot.manifest).unwrap();
    let meta = depot.manifest.objects.get(sha).unwrap();
    let err = crypto::decrypt_object(&key, sha, meta, &ct);
    assert!(err.is_err(), "tampered ciphertext must not decrypt");
}

#[test]
fn missing_objects_plans_incremental_download() {
    let root = fixture_root();
    let digest = expected_digest();
    let depot = FileDepot::open(&root, &digest).expect("open release");

    let referenced = app_lib::depot::referenced_objects(&depot.manifest, &depot.manifest.files);
    assert_eq!(referenced.len(), 2, "two distinct objects across the two files");

    // Nothing local: must fetch everything.
    let have = std::collections::HashSet::new();
    let missing = app_lib::depot::missing_objects(&depot.manifest.files, &have);
    assert_eq!(missing, referenced);

    // One object held: fetch only the other.
    let mut have = std::collections::HashSet::new();
    have.insert(referenced[0].clone());
    let missing = app_lib::depot::missing_objects(&depot.manifest.files, &have);
    assert_eq!(missing, vec![referenced[1].clone()]);

    // All held: nothing to download (the update is a local reassembly).
    let have = referenced.iter().cloned().collect();
    let missing = app_lib::depot::missing_objects(&depot.manifest.files, &have);
    assert!(missing.is_empty());
}

